import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 const output='docs/diario-ia/qa-resultados/camera-lateral';await mkdir(output,{recursive:true});
 const reports=[];
 for(const [profile,width,height,ua] of [
  ['desktop',960,540,'Mozilla/5.0 (Macintosh)'],
  ['android',390,844,'Mozilla/5.0 (Linux; Android 14) Mobile'],
  ['android-paisagem',844,390,'Mozilla/5.0 (Linux; Android 14) Mobile'],
  ['iphone',390,844,'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) Mobile'],
  ['iphone-paisagem',844,390,'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) Mobile']]) {
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:profile!=='desktop'});
  await call('Emulation.setUserAgentOverride',{userAgent:ua});
  await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html?cameraQa=1'});
  let ready=false;for(let i=0;i<200;i++){if(await evaluate('Boolean(window.review)')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Fixture de jogo real disponível');
  await evaluate(`document.head.insertAdjacentHTML('beforeend','<meta name="viewport" content="width=device-width,initial-scale=1"><style>canvas{width:100vw;height:100dvh}p{display:none}</style>')`);
  await evaluate('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');
  const result=await evaluate(`(async()=>{
   const {platforms,phase3Platforms}=await import('/src/js/config.js');
   const {CameraController}=await import('/src/js/controllers/CameraController.js');
   const {getDarkRoomScrollFrame}=await import('/src/js/controllers/CameraPresentation.js');
   const g=review.game,r=g.review,c=document.querySelector('canvas');let variants=0,visible=0,steps=0;
   window.cameraQaRecord=sample=>window.cameraSample=sample;
   function matrix(){r.renderManual();return window.cameraSample.transform;}
   function same(a,b,label){for(const key of ['a','b','c','d','e','f'])if(Math.abs(a[key]-b[key])>1e-8)throw Error(label+': '+key);}
   for(const phase3 of [false,true])for(let index=0;index<(phase3?phase3Platforms:platforms).length;index++){
    const p=(phase3?phase3Platforms:platforms)[index],support=p.standRegion||p;
    r.prepare(index,support.x+(support.w-38)/2,phase3);
    let saved=r.saveManual();saved.state.cameraX=g.state.baby.x-(phase3?(c.width>600?c.width-250:c.width-160):120);r.restoreManual(saved);
    const reference=matrix();
    for(const [dy,onGround,platform,zoom]of [[0,true,index,1],[-70,false,index,1],[-140,false,index,1],[0,true,index+1,1],[-70,false,index+1,1.25],[0,true,index,1.45]]){
     const v=structuredClone(saved);Object.assign(v.state.baby,{y:saved.state.baby.y+dy,vy:dy,onGround,currentPlatformIndex:platform});v.state.fairy.y+=dy*2;v.state.fairy.x+=dy;v.state.cameraY=dy;v.state.targetCameraY=dy;v.state.cameraZoom=zoom;
     r.restoreManual(v);const before=JSON.stringify(g.state.baby);same(reference,matrix(),'A matriz reagiu ao pulo/pouso '+phase3+'/'+index);if(before!==JSON.stringify(g.state.baby))throw Error('Desenho alterou o corpo');variants++;
    }
    r.restoreManual(saved);const m=matrix(),baby=g.state.baby,top=m.d*baby.y+m.f,feet=m.d*(baby.y+baby.h)+m.f;
    if(top<0||feet>c.height)throw Error('Menina fora do quadro no apoio '+index);visible++;
   }
   // A própria câmera também deve ignorar arco e apoio e nunca corrigir o corpo.
   for(const phase3 of [false,true]){
    r.prepare(phase3?7:15,2500,phase3);const base=r.saveManual().state;let ref;
    for(const [y,vy,onGround,index]of [[200,0,true,9],[-300,-10,false,9],[150,10,false,20],[100,0,true,21]]){
     const state=structuredClone(base);Object.assign(state.baby,{x:2500,y,vy,onGround,currentPlatformIndex:index});
     const camera=new CameraController({x:2300,y:19,zoom:1.4});const before=JSON.stringify(state.baby);
     camera.update(1,state,c,{escapeEndPlatformX:platforms.at(-1).x});
     if(before!==JSON.stringify(state.baby))throw Error('Câmera corrigiu salto/posição da menina');
     const pose=JSON.stringify([camera.x,camera.y,camera.zoom]);if(ref&&ref!==pose)throw Error('Câmera depende do arco ou do índice');ref=pose;
    }
   }
   const y=getDarkRoomScrollFrame({x:5000,width:c.width,height:c.height}).y;
   for(let x=5000;x>-2000;x-=50)if(getDarkRoomScrollFrame({x,width:c.width,height:c.height}).y!==y)throw Error('Existe rolagem vertical');
   // Executa saltos reais das duas seções posteriores; a matriz não varia durante o arco/pouso.
   for(const [phase3,targets]of [[false,[10,15,20,21]],[true,[0,7,14,15]]])for(const target of targets){
    const jump=review.run(target,1,phase3);const group=phase3?phase3Platforms:platforms;
    r.prepare(target-1,jump.launchX,phase3);r.jump();const first=matrix();
    for(let frame=0;frame<220;frame++){
     r.step(1);const m=matrix();for(const key of ['a','b','c','d','f'])if(Math.abs(first[key]-m[key])>1e-8)throw Error('Aterrissagem reajustou a matriz: '+key);
     steps++;if(g.isGameOver())throw Error('Regressão de salto real');if(g.state.baby.onGround){if(g.state.baby.currentPlatformIndex!==target)throw Error('Apoio errado');break;}
    }
   }
   return {variants,visible,steps,canvas:[c.width,c.height]};
  })()`);
  reports.push({profile,...result});
  for(const [phase3,index]of [[false,10],[false,20],[true,7],[true,15]]){
   await evaluate(`(async()=>{const {platforms,phase3Platforms}=await import('/src/js/config.js');const p=(${phase3}?phase3Platforms:platforms)[${index}],r=review.game.review,c=document.querySelector('canvas');r.prepare(${index},p.x+(p.w-38)/2,${phase3});const saved=r.saveManual();saved.state.cameraX=review.game.state.baby.x-(${phase3}?(c.width>600?c.width-250:c.width-160):120);r.restoreManual(saved);r.renderManual();})()`);
   const data=await evaluate("document.querySelector('canvas').toDataURL().split(',')[1]");const bytes=Buffer.from(data,'base64');await writeFile(output+'/'+profile+'-'+phase3+'-'+index+'.png',bytes);await writeFile('/tmp/legendgirl-lateral-'+profile+'-'+phase3+'-'+index+'.png',bytes);
  }
 }
 console.log(JSON.stringify(reports,null,2));console.log('APROVADO: matriz fixa nos saltos/pousos, somente rolagem lateral, câmera não altera o corpo e saltos reais preservados em cinco perfis.');

} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
